  "kapitulua": "01mc_05bektoriala",
  "atala": "a101",
  "atalaIzena": "Ariketa ebatziak (Griffiths eskuliburutik)",
  "izena": null,
  "izar": 0,
  "blokeak": [
   {
    "mota": "testua",
    "html": "Idatzi <math display=\"inline\"><mover><mi>s</mi><mo accent=\"true\">̂</mo></mover></math>, <math display=\"inline\"><mover><mi>φ</mi><mo accent=\"true\">̂</mo></mover></math>, <math display=\"inline\"><mover><mi>z</mi><mo accent=\"true\">̂</mo></mover></math> unitate-bektore zilindrikoak <math display=\"inline\"><mover><mi>x</mi><mo accent=\"true\">̂</mo></mover></math>, <math display=\"inline\"><mover><mi>y</mi><mo accent=\"true\">̂</mo></mover></math>, <math display=\"inline\"><mover><mi>z</mi><mo accent=\"true\">̂</mo></mover></math> kartesiarren funtzioan; ondoren alderantzikatu erlazioak."
   }
  ],
