    "blokeak": [
     {
      "mota": "testua",
      "html": "<math display=\"block\"><mrow><mi>l</mi><mo>=</mo><mn>8</mn><mspace width=\"1.0em\"></mspace><mi>✓</mi><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> (Em. ofiziala) </mtext><mspace width=\"0.333em\"></mspace></mrow></mrow></math>"
     }
    ]
