     {
      "mota": "testua",
      "html": "<math display=\"block\"><mrow><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> Sei ordena-trukeak eginda </mtext><mspace width=\"0.333em\"></mspace></mrow><mspace width=\"1.0em\"></mspace><mi>✓</mi></mrow></math>"
     }
