  "ebazpena": [
   {
    "mota": "testua",
    "html": "Koordenatu esferikoetan, <math display=\"inline\"><mrow><msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msup><mi>ρ</mi><mn>2</mn></msup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mrow><mn>3</mn><mi>/</mi><mn>2</mn></mrow></msup><mo>=</mo><msup><mi>ρ</mi><mn>3</mn></msup></mrow></math>: <math display=\"block\"><mrow><msubsup><mo>∫</mo><mn>0</mn><mrow><mn>2</mn><mi>π</mi></mrow></msubsup><msubsup><mo>∫</mo><mn>0</mn><mi>π</mi></msubsup><msubsup><mo>∫</mo><mi>a</mi><mi>b</mi></msubsup><mfrac><mrow><msup><mi>ρ</mi><mn>2</mn></msup><mrow><mi mathvariant=\"normal\">sin</mi><mo>&#8289;</mo></mrow><mi>ϕ</mi></mrow><msup><mi>ρ</mi><mn>3</mn></msup></mfrac><mi>d</mi><mi>ρ</mi><mi>d</mi><mi>ϕ</mi><mi>d</mi><mi>θ</mi><mo>=</mo><msubsup><mo>∫</mo><mn>0</mn><mrow><mn>2</mn><mi>π</mi></mrow></msubsup><msubsup><mo>∫</mo><mn>0</mn><mi>π</mi></msubsup><msubsup><mo>∫</mo><mi>a</mi><mi>b</mi></msubsup><mrow><mi mathvariant=\"normal\">sin</mi><mo>&#8289;</mo></mrow><mfrac><mi>ϕ</mi><mi>ρ</mi></mfrac><mi>d</mi><mi>ρ</mi><mi>d</mi><mi>ϕ</mi><mi>d</mi><mi>θ</mi></mrow></math> <math display=\"block\"><mrow><mo>=</mo><mn>2</mn><mi>π</mi><msubsup><mo>∫</mo><mi>a</mi><mi>b</mi></msubsup><msubsup><mo>∫</mo><mn>0</mn><mi>π</mi></msubsup><mrow><mi mathvariant=\"normal\">sin</mi><mo>&#8289;</mo></mrow><mfrac><mi>ϕ</mi><mi>ρ</mi></mfrac><mi>d</mi><mi>ϕ</mi><mi>d</mi><mi>ρ</mi><mo>=</mo><mn>2</mn><mi>π</mi><msubsup><mo>∫</mo><mi>a</mi><mi>b</mi></msubsup><mfrac><msubsup><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><mi>−</mi><mi mathvariant=\"normal\">cos</mi><mi>ϕ</mi><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow><mn>0</mn><mi>π</mi></msubsup><mi>ρ</mi></mfrac><mi>d</mi><mi>ρ</mi><mo>=</mo><mn>2</mn><mi>π</mi><mo>⋅</mo><mn>2</mn><msubsup><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><mi mathvariant=\"normal\">ln</mi><mi>ρ</mi><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow><mi>a</mi><mi>b</mi></msubsup></mrow></math>"
   }
  ]
