  "blokeak": [
   {
    "mota": "testua",
    "html": "Disko bat biraka dago erlojuaren orratzen noranzkoan orriaren planoan. Zein da diskoaren momentu angeluarraren orientazioa?"
   },
   {
    "mota": "zerrenda",
    "ordenatua": true,
    "etiketak": [
     "a)",
     "b)",
     "c)",
     "d)",
     "e)"
    ],
    "elementuak": [
     "erlojuaren orratzen arabera",
     "orritik irtenda, gorantza",
     "orrirantz goitik sartuz",
     "erlojuaren orratzen kontrakoa",
     "momentu angeluarrak ez du norabiderik"
    ]
   }
  ],
